#define CPPHTTPLIB_THREAD_POOL_COUNT 8
#include <winsock2.h>
#include <ws2tcpip.h>
#include <windows.h>
#include <condition_variable>
#include <functional>
#include <limits>
#include <mutex>
#include <thread>
#include <vector>
#include "../../third_party/httplib.h"
#include "../storage/store.hpp"
#include "../security/passwords.hpp"
#include "../services/healthcare_application.hpp"
#include <algorithm>
#include <cstdlib>
#include <map>
#include <mutex>
#include <cctype>
#include <cmath>

using namespace carebridge;
static Store* db=0;
static Passwords* passwords=0;
static HealthcareApplication* app=0;
static std::map<std::string,std::pair<std::string,std::time_t> > sessions;
static std::mutex sessionsMutex;
struct HttpFailure:std::runtime_error{int status;HttpFailure(int s,const std::string&m):std::runtime_error(m),status(s){}};
static void reply(httplib::Response&r,int status,const Json&j){r.status=status;r.set_content(j.dump(),"application/json; charset=utf-8");}
static void fail(httplib::Response&r,int status,const std::string&m){reply(r,status,Json{{"detail",m}});}
static Json body(const httplib::Request&q){try{Json j=Json::parse(q.body);if(!j.is_object())throw std::runtime_error("JSON object required");return j;}catch(...){throw HttpFailure(400,"Invalid JSON request body");}}
static std::string required(const Json&j,const std::string&k,std::size_t max=4096){if(!j.contains(k)||!j[k].is_string())throw HttpFailure(422,"Missing or invalid field: "+k);std::string s=j[k].get<std::string>();if(s.empty()||s.size()>max)throw HttpFailure(422,"Invalid field: "+k);if(k=="password"&&s.size()<8)throw HttpFailure(422,"Password must be at least 8 characters");return s;}
static Json userById(const std::string&id){for(const Json&u:db->list("users"))if(u.value("id",std::string())==id)return u;return Json();}
static Json auth(const httplib::Request&q,const std::string&role=""){
    std::string h=q.get_header_value("Authorization");if(h.compare(0,7,"Bearer ")!=0)throw HttpFailure(401,"Bearer token required");std::string token=h.substr(7),id;
    {std::lock_guard<std::mutex>l(sessionsMutex);std::map<std::string,std::pair<std::string,std::time_t> >::iterator i=sessions.find(token);if(i==sessions.end()||i->second.second<std::time(NULL)){if(i!=sessions.end())sessions.erase(i);throw HttpFailure(401,"Invalid or expired bearer token");}id=i->second.first;}
    Json u=userById(id);if(u.is_null())throw HttpFailure(401,"Account is unavailable");if(!role.empty()&&u.value("role",std::string())!=role){try{db->audit(id,u.value("role",std::string()),"authorization.denied",q.path,false,"role restriction");}catch(...){}throw HttpFailure(403,"Role is not permitted for this operation");}return u;
}
static void audit(const Json&u,const std::string&act,const std::string&resource,bool ok,const std::string&reason=""){try{db->audit(u.value("id",std::string("anonymous")),u.value("role",std::string("unknown")),act,resource,ok,reason);}catch(...){} }
static void guarded(const httplib::Request&q,httplib::Response&r,const std::function<void()>&fn){try{fn();}catch(const HttpFailure&e){fail(r,e.status,e.what());}catch(const ApplicationError&e){fail(r,e.status,e.what());}catch(const std::exception&e){fail(r,500,e.what());}catch(...){fail(r,500,"Internal server error");}}
static std::string identifier(){return newId();}
static bool hasConsent(const std::string&p,const std::string&d,const std::string&scope){for(const Json&c:db->list("consents"))if(c.value("patient_id",std::string())==p&&c.value("doctor_id",std::string())==d&&c.value("scope",std::string())==scope&&(c.value("status",std::string())=="active"||c.value("status",std::string())=="granted"))return true;return false;}
static double threshold(const char*name,double fallback){const char*v=std::getenv(name);if(!v)return fallback;char*end=0;double x=std::strtod(v,&end);return end&&*end=='\0'&&std::isfinite(x)&&x>0?x:fallback;}
static Json profileByUser(const std::string&id){for(const Json&p:db->list("patients"))if(p.value("user_id",std::string())==id)return p;return Json();}
static Json appointmentFor(const Json&a,const std::string&role){Json x=a;if(role=="patient"){Json d=userById(a.value("doctor_id",std::string()));x["doctor_name"]=d.value("full_name",std::string());x["specialty"]=d.value("specialty",std::string());}else{Json p=userById(a.value("patient_user_id",std::string()));x["patient_name"]=p.value("full_name",std::string());}return x;}

int main(int argc,char**argv){
    std::string file=argc>1?argv[1]:"data/carebridge.json";
    try{db=new Store(file);passwords=new Passwords();app=new HealthcareApplication(*db);}catch(const std::exception&e){std::fprintf(stderr,"CareBridge startup failed: %s\n",e.what());return 1;}
    httplib::Server server;server.set_payload_max_length(12*1024*1024);
    const char* origin=std::getenv("CAREBRIDGE_CORS_ORIGIN");const std::string allowed=origin?origin:"http://127.0.0.1:5173";
    auto cors=[allowed](const httplib::Request&,httplib::Response&r)->httplib::Server::HandlerResponse{r.set_header("Access-Control-Allow-Origin",allowed.c_str());r.set_header("Vary","Origin");r.set_header("Access-Control-Allow-Headers","Authorization, Content-Type, Accept");r.set_header("Access-Control-Allow-Methods","GET, POST, PATCH, DELETE, OPTIONS");return httplib::Server::HandlerResponse::Unhandled;};server.set_pre_routing_handler(cors);
    server.Options(".*",[](const httplib::Request&,httplib::Response&r){reply(r,200,Json::object());});
    server.Get("/health",[](const httplib::Request&,httplib::Response&r){reply(r,200,Json{{"status","ok"}});});
    auto registerUser=[](const httplib::Request&q,httplib::Response&r,const std::string&role){guarded(q,r,[&](){Json j=body(q);std::string email=required(j,"email",254),name=required(j,"full_name",150),pw=required(j,"password",256);std::transform(email.begin(),email.end(),email.begin(),[](unsigned char c){return (char)std::tolower(c);});if(email.find('@')==std::string::npos)throw HttpFailure(400,"Valid email required");for(const Json&u:db->list("users"))if(u.value("email",std::string())==email)throw HttpFailure(409,"An account with this email already exists");Json u={{"id",identifier()},{"email",email},{"full_name",name},{"role",role},{"password_hash",passwords->hash(pw)},{"is_active",true},{"created_at",timestamp()}};if(role=="doctor"){u["specialty"]=required(j,"specialty",120);u["registration_number"]=required(j,"registration_number",100);u["facility_name"]="CareBridge Clinic";u["facility_address"]="Synthetic demonstration clinic";}if(role=="lab_technician"){u["department"]=required(j,"department",80);}db->insert("users",u);if(role=="patient")db->insert("patients",Json{{"id",identifier()},{"user_id",u["id"]},{"date_of_birth",nullptr},{"phone",nullptr}});reply(r,201,Json{{"id",u["id"]},{"role",role}});});};
    server.Post("/auth/register",[registerUser](const httplib::Request&q,httplib::Response&r){registerUser(q,r,"patient");});
    server.Post("/auth/register/doctor",[registerUser](const httplib::Request&q,httplib::Response&r){registerUser(q,r,"doctor");});
    server.Post("/auth/register/lab-technician",[registerUser](const httplib::Request&q,httplib::Response&r){guarded(q,r,[&](){const char*s=std::getenv("CAREBRIDGE_PROVISION_KEY");Json j=body(q);if(!s||required(j,"provision_key",256)!=s)throw HttpFailure(403,"Technician provisioning is closed or key is invalid");registerUser(q,r,"lab_technician");});});
    server.Post("/auth/login",[](const httplib::Request&q,httplib::Response&r){guarded(q,r,[&](){Json j=body(q);std::string email=required(j,"email",254),pw=required(j,"password",256);std::transform(email.begin(),email.end(),email.begin(),[](unsigned char c){return (char)std::tolower(c);});for(const Json&u:db->list("users"))if(u.value("email",std::string())==email&&u.value("is_active",false)&&passwords->verify(pw,u.value("password_hash",std::string()))){std::string token=passwords->token();{std::lock_guard<std::mutex>l(sessionsMutex);sessions[token]=std::make_pair(u.value("id",std::string()),std::time(NULL)+28800);}reply(r,200,Json{{"access_token",token},{"token_type","bearer"},{"expires_in",28800}});return;}throw HttpFailure(401,"Invalid email or password");});});
    server.Get("/auth/me",[](const httplib::Request&q,httplib::Response&r){guarded(q,r,[&](){Json u=auth(q);reply(r,200,Json{{"id",u["id"]},{"email",u["email"]},{"full_name",u["full_name"]},{"role",u["role"]},{"is_active",true}});});});
    server.Post("/auth/logout",[](const httplib::Request&q,httplib::Response&r){guarded(q,r,[&](){std::string h=q.get_header_value("Authorization");if(h.compare(0,7,"Bearer ")!=0)throw HttpFailure(401,"Bearer token required");{std::lock_guard<std::mutex>l(sessionsMutex);sessions.erase(h.substr(7));}r.status=204;});});

    server.Get("/patients/me",[](const httplib::Request&q,httplib::Response&r){guarded(q,r,[&](){Json u=auth(q,"patient"),p=profileByUser(u["id"]);if(p.is_null())throw HttpFailure(404,"Patient profile not found");reply(r,200,p);});});
    server.Post("/patients/me",[](const httplib::Request&q,httplib::Response&r){guarded(q,r,[&](){Json u=auth(q,"patient"),j=body(q),p=profileByUser(u["id"]);if(p.is_null())throw HttpFailure(404,"Patient profile not found");if(j.contains("date_of_birth")&&!j["date_of_birth"].is_null()&&(!j["date_of_birth"].is_string()||j["date_of_birth"].get<std::string>().size()!=10))throw HttpFailure(400,"date_of_birth must be YYYY-MM-DD or null");p["date_of_birth"]=j.value("date_of_birth",Json(nullptr));p["phone"]=j.value("phone",Json(nullptr));db->update("patients",p["id"],p);reply(r,200,p);});});
    server.Get("/doctors/directory",[](const httplib::Request&,httplib::Response&r){Json out=Json::array();for(const Json&u:db->list("users"))if(u.value("role",std::string())=="doctor")out.push_back(Json{{"id",u["id"]},{"full_name",u["full_name"]},{"specialty",u["specialty"]},{"facility_name",u.value("facility_name",std::string())},{"facility_address",u.value("facility_address",std::string())}});reply(r,200,out);});
    server.Get(R"(/doctors/([^/]+)/availability)",[](const httplib::Request&q,httplib::Response&r){std::string id=q.matches[1];Json d=userById(id);if(d.is_null()||d.value("role",std::string())!="doctor"){fail(r,404,"Doctor not found");return;}Json slots=Json::array();const char* values[]={"09:00","09:30","10:00","10:30","11:00","13:00","13:30","14:00","14:30","15:00","15:30","16:00"};for(int i=0;i<12;i++)slots.push_back(values[i]);reply(r,200,Json{{"doctor_id",id},{"date",q.get_param_value("appointment_date")},{"slots",slots}});});

    server.Get("/patients/me/appointments",[](const httplib::Request&q,httplib::Response&r){guarded(q,r,[&](){Json u=auth(q,"patient"),out=Json::array();for(const Json&a:db->list("appointments"))if(a.value("patient_user_id",std::string())==u.value("id",std::string()))out.push_back(appointmentFor(a,"patient"));reply(r,200,out);});});
    server.Post("/patients/me/appointments",[](const httplib::Request&q,httplib::Response&r){guarded(q,r,[&](){Json u=auth(q,"patient"),j=body(q);std::string doctor=required(j,"doctor_id",80),when=required(j,"scheduled_at",80),reason=required(j,"reason",500);Json d=userById(doctor);if(d.is_null()||d.value("role",std::string())!="doctor")throw HttpFailure(404,"Doctor not found");Json a={{"id",identifier()},{"patient_user_id",u["id"]},{"patient_id",profileByUser(u["id"])["id"]},{"doctor_id",doctor},{"scheduled_at",when},{"reason",reason},{"status","booked"},{"created_at",timestamp()}};for(const Json&x:db->list("appointments"))if(x.value("doctor_id",std::string())==doctor&&x.value("scheduled_at",std::string())==when&&x.value("status",std::string())!="cancelled"&&x.value("status",std::string())!="rejected")throw HttpFailure(409,"Appointment time is no longer available");db->insert("appointments",a);reply(r,201,appointmentFor(a,"patient"));});});
    server.Post(R"(/patients/me/appointments/([^/]+)/cancel)",[](const httplib::Request&q,httplib::Response&r){guarded(q,r,[&](){Json u=auth(q,"patient"),a=db->find("appointments",q.matches[1]);if(a.is_null()||a.value("patient_user_id",std::string())!=u.value("id",std::string()))throw HttpFailure(404,"Appointment not found");a["status"]=HealthcareApplication::appointmentStatus(a,"cancelled");db->update("appointments",a["id"],a);reply(r,200,appointmentFor(a,"patient"));});});
    server.Get("/doctors/me/appointments",[](const httplib::Request&q,httplib::Response&r){guarded(q,r,[&](){Json u=auth(q,"doctor"),out=Json::array();for(const Json&a:db->list("appointments"))if(a.value("doctor_id",std::string())==u.value("id",std::string()))out.push_back(appointmentFor(a,"doctor"));reply(r,200,out);});});
    server.Patch(R"(/doctors/me/appointments/([^/]+))",[](const httplib::Request&q,httplib::Response&r){guarded(q,r,[&](){Json u=auth(q,"doctor"),j=body(q),a=db->find("appointments",q.matches[1]);if(a.is_null()||a.value("doctor_id",std::string())!=u.value("id",std::string()))throw HttpFailure(404,"Appointment not found");std::string s=required(j,"status",20);a["status"]=HealthcareApplication::appointmentStatus(a,s);db->update("appointments",a["id"],a);reply(r,200,Json::object());});});

    server.Get("/symptoms/catalog",[](const httplib::Request&,httplib::Response&r){reply(r,200,Json::array({{{"id","sym-headache"},{"name","Headache"},{"category","Neurological"},{"aliases",Json::array({"head pain"})}},{{"id","sym-fever"},{"name","Fever"},{"category","General"},{"aliases",Json::array({"high temperature"})}},{{"id","sym-cough"},{"name","Cough"},{"category","Respiratory"},{"aliases",Json::array()}},{{"id","sym-fatigue"},{"name","Fatigue"},{"category","General"},{"aliases",Json::array({"tiredness"})}},{{"id","sym-nausea"},{"name","Nausea"},{"category","Digestive"},{"aliases",Json::array()}}}));});
    server.Get("/patients/me/symptoms",[](const httplib::Request&q,httplib::Response&r){guarded(q,r,[&](){Json u=auth(q,"patient"),p=profileByUser(u["id"]),out=Json::array();for(const Json&s:db->list("symptoms"))if(s.value("patient_id",std::string())==p.value("id",std::string()))out.push_back(s);reply(r,200,out);});});
    server.Post("/patients/me/symptoms/structured",[](const httplib::Request&q,httplib::Response&r){guarded(q,r,[&](){Json u=auth(q,"patient"),p=profileByUser(u["id"]),j=body(q);if(!j.contains("symptom_ids")||!j["symptom_ids"].is_array()||j["symptom_ids"].empty()||j["symptom_ids"].size()>20)throw HttpFailure(400,"Select 1 to 20 symptoms");std::map<std::string,std::string>catalog;catalog["sym-headache"]="Headache";catalog["sym-fever"]="Fever";catalog["sym-cough"]="Cough";catalog["sym-fatigue"]="Fatigue";catalog["sym-nausea"]="Nausea";Json names=Json::array();for(const Json&id:j["symptom_ids"]){if(!id.is_string()||!catalog.count(id.get<std::string>()))throw HttpFailure(400,"Unknown symptom identifier");names.push_back(catalog[id.get<std::string>()]);}std::string severity=required(j,"severity",20);if(severity!="mild"&&severity!="moderate"&&severity!="severe")throw HttpFailure(400,"Invalid severity");Json s={{"id",identifier()},{"patient_id",p["id"]},{"symptom_ids",j["symptom_ids"]},{"symptom_names",names},{"symptoms",names.get<std::vector<std::string>>().size()?names.get<std::vector<std::string>>()[0]:std::string()},{"duration",required(j,"duration",100)},{"severity",severity},{"notes",j.value("notes",Json(nullptr))},{"status","reported"},{"created_at",timestamp()}};db->insert("symptoms",s);reply(r,201,s);});});

    server.Get("/patients/me/consents",[](const httplib::Request&q,httplib::Response&r){guarded(q,r,[&](){Json u=auth(q,"patient"),p=profileByUser(u["id"]),out=Json::array();for(const Json&c:db->list("consents"))if(c.value("patient_id",std::string())==p.value("id",std::string()))out.push_back(c);reply(r,200,out);});});
    server.Post("/patients/me/consents",[](const httplib::Request&q,httplib::Response&r){guarded(q,r,[&](){Json u=auth(q,"patient"),p=profileByUser(u["id"]),j=body(q);std::string d=required(j,"doctor_id",80),s=required(j,"scope",40);Json doc=userById(d);if(doc.is_null()||doc.value("role",std::string())!="doctor")throw HttpFailure(404,"Doctor not found");if(s!="profile"&&s!="medical_history"&&s!="vitals")throw HttpFailure(400,"Unsupported consent scope");Json c={{"id",identifier()},{"patient_id",p["id"]},{"doctor_id",d},{"scope",s},{"status","granted"},{"created_at",timestamp()},{"revoked_at",nullptr}};for(const Json&old:db->list("consents"))if(old.value("patient_id",std::string())==c["patient_id"]&&old.value("doctor_id",std::string())==d&&old.value("scope",std::string())==s&&old.value("status",std::string())=="granted")throw HttpFailure(409,"Consent is already active");db->insert("consents",c);audit(u,"consent.grant",c["id"],true);reply(r,201,c);});});
    server.Post(R"(/patients/me/consents/([^/]+)/revoke)",[](const httplib::Request&q,httplib::Response&r){guarded(q,r,[&](){Json u=auth(q,"patient"),p=profileByUser(u["id"]),c=db->find("consents",q.matches[1]);if(c.is_null()||c.value("patient_id",std::string())!=p.value("id",std::string()))throw HttpFailure(404,"Consent not found");c["status"]="revoked";c["revoked_at"]=timestamp();db->update("consents",c["id"],c);audit(u,"consent.revoke",c["id"],true);reply(r,200,c);});});

    server.Get("/doctors/me/profile",[](const httplib::Request&q,httplib::Response&r){guarded(q,r,[&](){Json u=auth(q,"doctor");reply(r,200,Json{{"id",u["id"]},{"full_name",u["full_name"]},{"email",u["email"]},{"specialty",u["specialty"]},{"registration_number",u["registration_number"]},{"facility_name",u.value("facility_name",std::string())},{"facility_address",u.value("facility_address",std::string())}});});});
    server.Get("/doctors/me/lab-technicians",[](const httplib::Request&q,httplib::Response&r){guarded(q,r,[&](){reply(r,200,app->technicians(auth(q,"doctor")));});});
    server.Get("/doctors/me/patients",[](const httplib::Request&q,httplib::Response&r){guarded(q,r,[&](){Json d=auth(q,"doctor"),out=Json::array();for(const Json&p:db->list("patients")){if(!hasConsent(p.value("id",std::string()),d.value("id",std::string()),"medical_history"))continue;Json u=userById(p.value("user_id",std::string())),sym=Json::array();for(const Json&s:db->list("symptoms"))if(s.value("patient_id",std::string())==p.value("id",std::string()))sym.push_back(s);bool profile=hasConsent(p.value("id",std::string()),d.value("id",std::string()),"profile");out.push_back(Json{{"patient_id",p["id"]},{"full_name",u.value("full_name",std::string())},{"date_of_birth",profile?p.value("date_of_birth",Json(nullptr)):Json(nullptr)},{"phone",profile?p.value("phone",Json(nullptr)):Json(nullptr)},{"symptoms",sym}});}reply(r,200,out);});});
    server.Post(R"(/doctors/me/patients/([^/]+)/records)",[](const httplib::Request&q,httplib::Response&r){guarded(q,r,[&](){Json d=auth(q,"doctor"),j=body(q);std::string p=q.matches[1];if(db->find("patients",p).is_null()||!hasConsent(p,d.value("id",std::string()),"medical_history")){audit(d,"record.create",p,false,"patient history consent missing");throw HttpFailure(403,"Patient history consent required");}std::string type=required(j,"record_type",20);if(type!="diagnosis"&&type!="note")throw HttpFailure(400,"Invalid record type");std::string title=required(j,"title",200),content=required(j,"content",10000);if(title.size()<2||content.size()<2)throw HttpFailure(400,"Record title and content are too short");Json x={{"id",identifier()},{"patient_id",p},{"doctor_id",d["id"]},{"record_type",type},{"title",title},{"content",content},{"created_at",timestamp()}};db->insert("records",x);audit(d,"record.create",x["id"],true);reply(r,201,x);});});
    server.Post(R"(/doctors/me/patients/([^/]+)/prescriptions)",[](const httplib::Request&q,httplib::Response&r){guarded(q,r,[&](){Json d=auth(q,"doctor"),j=body(q);std::string p=q.matches[1];if(db->find("patients",p).is_null()||!hasConsent(p,d.value("id",std::string()),"medical_history"))throw HttpFailure(403,"Patient history consent required");std::string name=required(j,"filename",255),type=required(j,"content_type",80),data=required(j,"file_base64",12000000);if(name.find_first_of("/\\")!=std::string::npos||!(type=="application/pdf"||type=="image/jpeg"||type=="image/png")||data.size()>11184812)throw HttpFailure(400,"Invalid prescription file");Json x={{"id",identifier()},{"patient_id",p},{"doctor_id",d["id"]},{"filename",name},{"content_type",type},{"file_base64",data},{"created_at",timestamp()}};db->insert("prescriptions",x);audit(d,"prescription.create",x["id"],true);reply(r,201,Json{{"id",x["id"]}});});});
    server.Post(R"(/doctors/me/patients/([^/]+)/followups)",[](const httplib::Request&q,httplib::Response&r){guarded(q,r,[&](){Json d=auth(q,"doctor"),j=body(q);std::string p=q.matches[1];if(db->find("patients",p).is_null()||!hasConsent(p,d.value("id",std::string()),"medical_history"))throw HttpFailure(403,"Patient history consent required");std::string at=required(j,"scheduled_at",80),reason=required(j,"reason",300);Json pat=db->find("patients",p);Json a={{"id",identifier()},{"patient_user_id",pat["user_id"]},{"patient_id",p},{"doctor_id",d["id"]},{"scheduled_at",at},{"reason","Follow-up: "+reason},{"status","approved"},{"created_at",timestamp()}};db->insert("appointments",a);reply(r,201,a);});});
    server.Get("/patients/me/clinical-records",[](const httplib::Request&q,httplib::Response&r){guarded(q,r,[&](){Json u=auth(q,"patient"),p=profileByUser(u["id"]),out=Json::array();for(const Json&x:db->list("records"))if(x.value("patient_id",std::string())==p.value("id",std::string()))out.push_back(x);reply(r,200,out);});});
    server.Get("/patients/me/prescriptions",[](const httplib::Request&q,httplib::Response&r){guarded(q,r,[&](){Json u=auth(q,"patient"),p=profileByUser(u["id"]),out=Json::array();for(const Json&x:db->list("prescriptions"))if(x.value("patient_id",std::string())==p.value("id",std::string()))out.push_back(Json{{"id",x["id"]},{"filename",x["filename"]},{"content_type",x["content_type"]},{"created_at",x["created_at"]}});reply(r,200,out);});});
    server.Get(R"(/patients/me/prescriptions/([^/]+)/download)",[](const httplib::Request&q,httplib::Response&r){guarded(q,r,[&](){Json u=auth(q,"patient"),p=profileByUser(u["id"]),x=db->find("prescriptions",q.matches[1]);if(x.is_null()||x.value("patient_id",std::string())!=p.value("id",std::string()))throw HttpFailure(404,"Prescription not found");reply(r,200,Json{{"filename",x["filename"]},{"content_type",x["content_type"]},{"file_base64",x["file_base64"]}});});});

    server.Post(R"(/doctors/me/patients/([^/]+)/lab-orders)",[](const httplib::Request&q,httplib::Response&r){guarded(q,r,[&](){Json d=auth(q,"doctor"),o=app->createLabOrder(d,q.matches[1],body(q));reply(r,201,o);});});
    server.Get("/doctors/me/lab-orders",[](const httplib::Request&q,httplib::Response&r){guarded(q,r,[&](){Json d=auth(q,"doctor"),out=Json::array();for(const Json&o:db->list("lab_orders"))if(o.value("doctor_id",std::string())==d.value("id",std::string()))out.push_back(o);reply(r,200,out);});});
    server.Get("/lab/me/orders",[](const httplib::Request&q,httplib::Response&r){guarded(q,r,[&](){reply(r,200,app->assignedOrders(auth(q,"lab_technician")));});});
    server.Get(R"(/lab/me/orders/([^/]+))",[](const httplib::Request&q,httplib::Response&r){guarded(q,r,[&](){Json t=auth(q,"lab_technician");reply(r,200,app->labOrderDetails(t,q.matches[1]));});});
    server.Post(R"(/lab/me/orders/([^/]+)/start)",[](const httplib::Request&q,httplib::Response&r){guarded(q,r,[&](){Json t=auth(q,"lab_technician");reply(r,200,app->startLabOrder(t,q.matches[1]));});});
    server.Post(R"(/lab/me/orders/([^/]+)/results)",[](const httplib::Request&q,httplib::Response&r){guarded(q,r,[&](){Json t=auth(q,"lab_technician");reply(r,201,app->submitLabResults(t,q.matches[1],body(q)));});});
    server.Get("/patients/me/lab-results",[](const httplib::Request&q,httplib::Response&r){guarded(q,r,[&](){Json p=profileByUser(auth(q,"patient")["id"]),out=Json::array();for(const Json&x:db->list("lab_results"))if(x.value("patient_id",std::string())==p.value("id",std::string()))out.push_back(x);reply(r,200,out);});});
    server.Get("/doctors/me/lab-results",[](const httplib::Request&q,httplib::Response&r){guarded(q,r,[&](){Json d=auth(q,"doctor"),out=Json::array();std::string p=q.has_param("patient_id")?q.get_param_value("patient_id"):std::string();for(const Json&o:db->list("lab_orders"))if(o.value("doctor_id",std::string())==d.value("id",std::string())&&(p.empty()||o.value("patient_id",std::string())==p)){if(!hasConsent(o.value("patient_id",std::string()),d.value("id",std::string()),"medical_history")){audit(d,"lab_result.read",o.value("id",std::string()),false,"patient consent revoked");throw HttpFailure(403,"Patient consent required to view results");}for(const Json&x:db->list("lab_results"))if(x.value("order_id",std::string())==o.value("id",std::string()))out.push_back(x);}reply(r,200,out);});});

    server.Post("/patients/me/vitals",[](const httplib::Request&q,httplib::Response&r){guarded(q,r,[&](){Json u=auth(q,"patient"),p=profileByUser(u["id"]),j=body(q);const char*keys[]={"systolic_bp","diastolic_bp","heart_rate","temperature_c","oxygen_saturation","weight_kg"};bool any=false;for(unsigned i=0;i<6;i++)if(j.contains(keys[i])&&!j[keys[i]].is_null()){if(!j[keys[i]].is_number()||j[keys[i]].get<double>()<=0||j[keys[i]].get<double>()>100000)throw HttpFailure(400,std::string("Invalid vital: ")+keys[i]);any=true;}if(!any)throw HttpFailure(400,"At least one vital value is required");Json v={{"id",identifier()},{"patient_id",p["id"]},{"systolic_bp",j.value("systolic_bp",Json(nullptr))},{"diastolic_bp",j.value("diastolic_bp",Json(nullptr))},{"heart_rate",j.value("heart_rate",Json(nullptr))},{"temperature_c",j.value("temperature_c",Json(nullptr))},{"oxygen_saturation",j.value("oxygen_saturation",Json(nullptr))},{"weight_kg",j.value("weight_kg",Json(nullptr))},{"notes",j.value("notes",Json(nullptr))},{"simulated",true},{"recorded_at",timestamp()}};db->insert("vitals",v);const double hr=v.value("heart_rate",0.0),spo=v.value("oxygen_saturation",100.0),hrLimit=threshold("CAREBRIDGE_ALERT_HR_HIGH",120.0),spoLimit=threshold("CAREBRIDGE_ALERT_SPO2_LOW",90.0);if(hr>hrLimit||spo<spoLimit){Json al={{"id",identifier()},{"patient_id",p["id"]},{"severity",hr>hrLimit*1.25||spo<spoLimit-5?"high":"medium"},{"reason",hr>hrLimit?"Synthetic heart-rate demonstration threshold crossed":"Synthetic oxygen-saturation demonstration threshold crossed"},{"status","open"},{"created_at",timestamp()},{"simulated",true}};db->insert("alerts",al);}audit(u,"vital.create",v["id"],true);reply(r,201,v);});});
    server.Get("/patients/me/vitals",[](const httplib::Request&q,httplib::Response&r){guarded(q,r,[&](){Json p=profileByUser(auth(q,"patient")["id"]),out=Json::array();for(const Json&x:db->list("vitals"))if(x.value("patient_id",std::string())==p.value("id",std::string()))out.push_back(x);reply(r,200,out);});});
    server.Get("/patients/me/timeline",[](const httplib::Request&q,httplib::Response&r){guarded(q,r,[&](){Json u=auth(q,"patient"),p=profileByUser(u["id"]),out=Json::array();std::string pid=p.value("id",std::string());for(const Json&x:db->list("records"))if(x.value("patient_id",std::string())==pid)out.push_back(Json{{"id",x["id"]},{"category","visit"},{"title",x["title"]},{"date",x["created_at"]},{"source","Clinician record"},{"description",x["content"]}});for(const Json&x:db->list("prescriptions"))if(x.value("patient_id",std::string())==pid)out.push_back(Json{{"id",x["id"]},{"category","prescription"},{"title",x["filename"]},{"date",x["created_at"]},{"source","Clinician prescription"}});for(const Json&x:db->list("lab_results"))if(x.value("patient_id",std::string())==pid)out.push_back(Json{{"id",x["id"]},{"category","lab_result"},{"title",x["test_name"]},{"date",x["timestamp"]},{"source","Laboratory result"},{"description",std::to_string(x.value("value",0.0))+" "+x.value("unit",std::string())}});for(const Json&x:db->list("vitals"))if(x.value("patient_id",std::string())==pid)out.push_back(Json{{"id",x["id"]},{"category","vital"},{"title","Synthetic vital reading"},{"date",x["recorded_at"]},{"source","Patient entered (simulated)"}});audit(u,"timeline.read",pid,true);reply(r,200,out);});});
    server.Get("/patients/me/alerts",[](const httplib::Request&q,httplib::Response&r){guarded(q,r,[&](){Json p=profileByUser(auth(q,"patient")["id"]),out=Json::array();for(const Json&x:db->list("alerts"))if(x.value("patient_id",std::string())==p.value("id",std::string()))out.push_back(x);reply(r,200,out);});});
    server.Post(R"(/patients/me/alerts/([^/]+)/acknowledge)",[](const httplib::Request&q,httplib::Response&r){guarded(q,r,[&](){Json p=profileByUser(auth(q,"patient")["id"]),x=db->find("alerts",q.matches[1]);if(x.is_null()||x.value("patient_id",std::string())!=p.value("id",std::string()))throw HttpFailure(404,"Alert not found");x["status"]="acknowledged";db->update("alerts",x["id"],x);reply(r,200,x);});});

    server.set_error_handler([](const httplib::Request&,httplib::Response&r){if(r.body.empty())fail(r,r.status,"Request failed");});
    int port=8001;if(const char*p=std::getenv("CAREBRIDGE_PORT")){int n=std::atoi(p);if(n>0&&n<65536)port=n;}
    std::printf("CareBridge API listening on http://127.0.0.1:%d with data file %s\n",port,file.c_str());
    if(!server.listen("127.0.0.1",port)){std::fprintf(stderr,"Could not bind port %d\n",port);return 2;}return 0;
}